{"api_file": {"path": "src/api/productConsumptionApi.ts", "content": "const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface ProductConsumption {
  productConsumptionId: number;
  companyId: number;
  productId: number;
  productOptionChoiceId: number | null;
  componentProductId: number;
  componentProductOptionChoiceId: number | null;
  quantity: number;
  isActive: boolean;
  created_At: string;
  updated_at: string | null;
}

export interface ProductConsumptionListResponse {
  productConsumptions: ProductConsumption[];
}

// GET ALL — POST /all_productConsumptions
export async function getAllProductConsumptions(companyId: number, productId?: number, productOptionChoiceId?: number): Promise<ProductConsumption[]> {
  const payload: any = {
    companyId: companyId
  };
  if (productId) payload.productId = productId;
  if (productOptionChoiceId) payload.productOptionChoiceId = productOptionChoiceId;

  const res = await fetch(BASE_URL + "/all_productConsumptions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "productConsumptions": [payload] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: ProductConsumptionListResponse = await res.json();
  return data.productConsumptions ?? [];
}

// CREATE — action: 1
export async function createProductConsumption(payload: Omit<ProductConsumption, "productConsumptionId" | "created_At" | "updated_at">): Promise<ProductConsumption> {
  const res = await fetch(BASE_URL + "/productConsumptions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "productConsumptions": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// UPDATE — action: 2
export async function updateProductConsumption(id: number, payload: Partial<Omit<ProductConsumption, "productConsumptionId" | "created_At" | "updated_at" | "companyId">>): Promise<ProductConsumption> {
  const res = await fetch(BASE_URL + "/productConsumptions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "productConsumptions": [{ "action": 2, "productConsumptionId": id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// DELETE — action: 3
export async function deleteProductConsumption(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/productConsumptions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "productConsumptions": [{ "action": 3, "productConsumptionId": id, "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}
