import { useIonViewWillEnter } from '@ionic/react';
import { useUser } from '../../../contexts/UserContext';
import { useToast } from '../../../hooks/useToast';
import { onDataChanged, notifyDataChanged } from '../../../utils/refreshBus';
import {
  getAllProductConsumptions, createProductConsumption,
  updateProductConsumption, deleteProductConsumption, ProductConsumption
} from '../../../api/productConsumptionApi';
import { getAllProducts, Product } from '../../../api/productsApi'; // Assuming productsApi exists to get product names

interface ProductConsumptionFormState {
  productId: number | null;
  productOptionChoiceId: number | null;
  componentProductId: number | null;
  componentProductOptionChoiceId: number | null;
  quantity: number;
  isActive: boolean;
}

const initialFormState: ProductConsumptionFormState = {
  productId: null,
  productOptionChoiceId: null,
  componentProductId: null,
  componentProductOptionChoiceId: null,
  quantity: 0,
  isActive: true,
};

export const useProductConsumption = () => {
  const { companyId } = useUser();
  const { showToast, toastProps } = useToast();
  const [items, setItems] = useState<ProductConsumption[]>([]);
  const [products, setProducts] = useState<Product[]>([]); // For dropdowns
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [formState, setFormState] = useState<ProductConsumptionFormState>(initialFormState);
  const [selectedItem, setSelectedItem] = useState<ProductConsumption | null>(null);
  const [deleteAlert, setDeleteAlert] = useState<ProductConsumption | null>(null);

  const loadProducts = useCallback(async () => {
    try {
      const allProducts = await getAllProducts(companyId);
      setProducts(allProducts);
    } catch (err) {
      showToast((err as Error).message ?? 'Error cargando productos', 'danger');
    }
  }, [companyId, showToast]);

  const loadConsumptions = useCallback(async () => {
    setLoading(true);
    try {
      const data = await getAllProductConsumptions(companyId);
      setItems(data);
    } catch (err) {
      showToast((err as Error).message ?? 'Error cargando consumos de productos', 'danger');
    } finally {
      setLoading(false);
    }
  }, [companyId, showToast]);

  useEffect(() => {
    loadConsumptions();
    loadProducts();
  }, [loadConsumptions, loadProducts]);

  useIonViewWillEnter(() => {
    loadConsumptions();
    loadProducts();
  });

  useEffect(() => onDataChanged(() => {
    loadConsumptions();
    loadProducts();
  }), [loadConsumptions, loadProducts]);

  const handleAddClick = () => {
    setIsEditing(false);
    setFormState(initialFormState);
    setSelectedItem(null);
    setShowModal(true);
  };

  const handleEditClick = (item: ProductConsumption) => {
    setIsEditing(true);
    setFormState({
      productId: item.productId,
      productOptionChoiceId: item.productOptionChoiceId,
      componentProductId: item.componentProductId,
      componentProductOptionChoiceId: item.componentProductOptionChoiceId,
      quantity: item.quantity,
      isActive: item.isActive,
    });
    setSelectedItem(item);
    setShowModal(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formState.productId || !formState.componentProductId || formState.quantity <= 0) {
      showToast('Por favor, completa todos los campos requeridos y asegúrate que la cantidad sea mayor a cero.', 'warning');
      return;
    }

    setSaving(true);
    try {
      if (isEditing && selectedItem) {
        await updateProductConsumption(selectedItem.productConsumptionId, formState);
        showToast('Regla de consumo actualizada con éxito', 'success');
      } else {
        await createProductConsumption({ ...formState, companyId: companyId as number, created_At: new Date().toISOString() });
        showToast('Regla de consumo creada con éxito', 'success');
      }
      setShowModal(false);
      notifyDataChanged('productConsumptions-saved');
    } catch (err) {
      showToast((err as Error).message ?? 'Error al guardar la regla de consumo', 'danger');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: number) => {
    setLoading(true);
    try {
      await deleteProductConsumption(id, companyId);
      showToast('Regla de consumo eliminada con éxito', 'success');
      notifyDataChanged('productConsumptions-saved');
    } catch (err) {
      showToast((err as Error).message ?? 'Error al eliminar la regla de consumo', 'danger');
    } finally {
      setLoading(false);
      setDeleteAlert(null);
    }
  };

  const handleModalDismiss = () => {
    setShowModal(false);
    setFormState(initialFormState);
    setSelectedItem(null);
  };

  return {
    items,
    products,
    loading,
    saving,
    showModal,
    isEditing,
    formState,
    selectedItem,
    deleteAlert,
    toastProps,
    handleAddClick,
    handleEditClick,
    handleSave,
    handleDelete,
    handleModalDismiss,
    setFormState,
    setDeleteAlert,
  };
};

export type ProductConsumptionVM = ReturnType<typeof useProductConsumption>;
